function visitsPage(){const v=chosen("visits"),vv=v?C.visitView(w,v.id):null,j=vv?.job||chosen("jobs"),canEdit=!v||vv.canEdit,started=v?.status==="started";return `<div class="layout"><div>${listPanel("visits","Visits")}</div><div><section class="panel"><h2>${v?"Visit and assignment":"Request a visit"}</h2>${reference(v)}${v&&!canEdit?`<div class="preserved">This visit retains its original job/site/appliance snapshot. Started or closed work cannot be moved; record a successor visit.</div><dl><dt>Site</dt><dd>${esc(vv.site?.propertyRef)} · ${esc(vv.site?.address)}</dd><dt>Appliance</dt><dd>${esc(vv.appliance?.label)} · ${esc(vv.appliance?.makeModel)}</dd><dt>Scope</dt><dd>${esc(vv.job?.scope)}</dd><dt>Access</dt><dd>${esc(vv.site?.access)}</dd></dl>`:""}${form("visit",select("jobId","Job",opts("jobs",x=>x.status!=="cancelled"),v?.jobId||selected.jobs,{required:true,disabled:!!v})+select("kind","Visit type",["survey","installation","service","sweep","repair","other"],v?.kind,{required:true})+input("startAt","Planned start (ISO with offset)",v?.startAt,"text",{placeholder:"2026-10-15T09:00:00+01:00"})+input("endAt","Planned finish (ISO with offset)",v?.endAt,"text",{placeholder:"2026-10-15T11:00:00+01:00"})+input("timezone","IANA timezone label",v?.timezone,"text",{placeholder:"Europe/London"})+area("workerRefs","Assigned worker references",arr(v?.workerRefs).join("\n"),{hint:"One actual worker reference per line. No availability is inferred from a public staff list."})+area("notes","Visit notes",v?.notes),"Save requested visit",!canEdit)}${v&&canEdit?`<div class="actions">${button("review-visit","Review confirmation",{id:v.id})}</div><div id="visit-review"></div>${form("visit-cancel",area("reason","Reason to cancel","",{required:true}),"Cancel requested / confirmed visit")}`:""}${vv?.canStart?form("visit-start",input("startedAt","Actual start (ISO with offset)","","text",{required:true})+input("author","Responsible worker","","text",{required:true}),"Start visit"):""}</section>${v?`<section class="panel"><h2>Actual field observations</h2>${arr(vv.fieldRecords).map(x=>details(`${x.recordedAt} · ${x.author}`,`<p>${esc(x.notes)}</p>${table(["Measurement","Value","Unit","Source"],arr(x.measurements).map(m=>[m.label,m.value,m.unit,m.source].map(esc)))}${table(["Check","Result","Notes"],arr(x.checkResults).map(c=>[esc(c.checkId),tag(c.result),esc(c.notes)]))}<p>${arr(x.attachmentIds).map(id=>button("attachment-download",name("attachments",id),{id})).join(" ")}</p>${details("Exact field record",json(x))}`)).join("")||empty("No field observation recorded yet.")}${started?form("field",input("recordedAt","Actual observation time (ISO with offset)","","text",{required:true})+input("author","Observer reference","","text",{required:true})+area("notes","Actual work and observations","",{required:true})+area("measurements","Measurements","",{hint:"One row: label | retained value | unit | source."})+arr(vv.job?.checklist).map(x=>`<fieldset class="wide"><legend>${esc(x.label)}${x.required?" · required":""}</legend><div class="grid">${select("check-result-"+x.id,"Observed result",["pass","fail","not-applicable"])}${input("check-evidence-"+x.id,"Comma-separated original evidence IDs")}${area("check-notes-"+x.id,"Notes / basis")}</div><p class="hint">${x.evidenceRequired?"Passing this check requires retained original evidence.":"Leave blank if this observation does not address the check."}</p></fieldset>`).join("")+filesSelector(),"Append field record"):`<p class="small muted">Field observations append during a started visit. Closed records are retained; later work uses another visit.</p>`}</section>${started?`<section class="panel"><h2>Close this field visit</h2>${form("visit-finish",input("finishedAt","Actual finish (ISO with offset)","","text",{required:true})+input("author","Responsible worker","","text",{required:true})+area("notes","Finish notes"),"Finish visit",!vv.canFinish)}${form("visit-abort",input("finishedAt","Actual withdrawal time (ISO with offset)","","text",{required:true})+input("author","Responsible worker","","text",{required:true})+area("reason","Reason to stop and outstanding work","",{required:true}),"Abort visit",!vv.canAbort)}<p class="small">Finishing a visit does not complete the job or its handover. An aborted visit retains its partial observations.</p></section>`:""}${details("Full preserved visit source",json(vv))}`:""}</div></div>`}


const importFields={site:["customerRef","propertyRef","address","contact","access","notes"],appliance:["siteRef","label","makeModel","serialNumber","fuelType","location","installedOn","notes"],enquiry:["siteRef","applianceId","kind","title","reference","requestedDate","details"]},entityCollection={site:"sites",appliance:"appliances",enquiry:"enquiries"};
function filesPage(){return `<section class="panel"><h2>Retain an original file</h2><p>Original bytes and names are retained. Files up to 8 MiB each fit within the complete workspace’s 64 MiB limit. Keep an exported working copy after adding evidence.</p>${form("attachment",input("original","Choose original file","","file",{required:true})+input("description","Purpose / original context")+select("siteId","Related site (optional)",opts("sites"))+select("jobId","Related job (optional)",opts("jobs")),"Retain original file")}<div id="file-progress"></div></section><section class="panel"><h2>Retained originals</h2>${table(["Original","Association","Identity","Download"],arr(w.attachments).filter(x=>!x.siteId&&!x.jobId||belongs(x)).map(x=>[esc(x.name)+"<br>"+esc(x.description),esc(x.jobId?name("jobs",x.jobId):x.siteId?name("sites",x.siteId):"Workspace source"),`${esc(x.bytes)} bytes<br>Record <code>${esc(x.id)}</code><br>SHA-256 <code>${esc(x.sha256)}</code>`,button("attachment-download","Original file",{id:x.id})]))}</section><section class="panel"><h2>Reviewed CSV intake</h2><p>Retain the original CSV above, then choose its fields and every row decision. Existing linked records are not overwritten.</p>${form("import-select",select("attachmentId","Original CSV",attachmentOptions(),importInput?.attachmentId,{required:true})+select("entity","Record type",["site","appliance","enquiry"],importInput?.entity,{required:true}),"Inspect original headers")}${importReview?`<p class="small">Original ${esc(name("attachments",importInput.attachmentId))} · ${importReview.rows.length} rows · reviewed at workspace revision ${importReview.revision}</p>${form("import-map",importFields[importInput.entity].map(field=>select("map-"+field,field+" — source header",arr(importReview.headers),importInput.mapping?.[field])+input("constant-"+field,field+" — explicit constant",importInput.constants?.[field],"text",{hint:"Use a header or a constant, not both."})).join("")+(["appliance","enquiry"].includes(importInput.entity)?select("constant-siteId","Explicit site instead of siteRef",opts("sites"),importInput.constants?.siteId):""),"Review mapped rows")}${issueList(importReview)}${form("import-decisions",`<div class="wide">${table(["Original row","Proposed record","Decision","Target / reason"],arr(importReview.rows).map(row=>[`${esc(row.line)}<br>${details("Exact original row",json(row.source))}`,json(row.proposed)+arr(row.issues).map(x=>`<p>${esc(x.message||x)}</p>`).join(""),select("action-"+row.rowId,"Action",["create","link","ignore"]),input("new-"+row.rowId,"ID for a created record",C.uid(importInput.entity))+select("target-"+row.rowId,"Link existing",opts(entityCollection[importInput.entity]))+input("reason-"+row.rowId,"Reason / decision note")]))}</div>`,"Commit all explicit decisions")}`:""}<p class="small">Original CSV, mapping, constants and each row’s decision remain in the complete saved history.</p></section><section class="panel"><h2>Retained import decisions</h2>${arr(w.imports).filter(x=>x.operatorKey===op||x.input?.operatorKey===op).map(x=>details(x.id,json(x))).join("")||empty("No committed import yet.")}</section>`}
function workspacePage(){return `<section class="panel"><h2>Working copy and complete receiving</h2><p>${esc(w.title)} · revision ${w.revision} · <code>${esc(w.id)}</code></p><p>Download the complete working JSON to keep original files, all companies and the full change history. Receive that JSON here to continue it independently.</p><div class="actions">${button("export-working","Download complete working JSON",{},"primary")}${button("save-browser","Save separate browser copy")}${button("load-browser","Review saved browser copy")}</div><label>Choose an existing full working JSON <input id="workspace-file" type="file" accept=".json,application/json"></label><div id="incoming-review">${pendingWorkspace?incomingView():""}</div></section><section class="panel"><h2>Readable exports</h2><p>Reports summarize work and references. Original documents and full snapshots remain in the complete working file.</p><div class="actions">${button("export-report","Selected company report")}${button("export-csv","Selected company CSV")}${button("export-all-report","All-company report")}${button("export-all-csv","All-company CSV")}</div></section><section class="panel"><h2>Worked programme and fresh workspace</h2><p>The worked programme uses the six published company workflows with explicitly fictional customer, site, timing and field examples. Loading it replaces this working copy only after confirmation.</p><div class="actions">${button("example","Load complete worked programme",{},"",busy)}${button("new-workspace","Create an empty workspace")}</div><div id="example-progress" class="small" aria-live="polite"></div></section><section class="panel"><h2>Latest recorded actions</h2><p class="small">Showing the latest 50 of ${arr(w.history).length} actions. Complete export retains every action.</p>${table(["Revision","Action","Time / actor"],arr(w.history).slice(-50).reverse().map(x=>[esc(x.revision||x.atRevision||""),esc(x.type||x.command?.type||x.action||"Recorded change"),esc(x.at||x.timestamp||"")+"<br>"+esc(x.actor||"")]))}${details("Complete workspace summary",json(C.summary(w)))}</section>`}
function incomingView(){const q=pendingWorkspace;if(!q)return "";return `<div class="notice"><strong>Validated separate working copy</strong><p>${esc(q.workspace.title)} · revision ${q.workspace.revision} · ${esc(q.workspace.id)}</p><p>${q.bytes} bytes · JSON value identity <code>${esc(q.sha)}</code></p>${table(["Sites","Jobs","Visits","Original files"],[[q.summary.sites,q.summary.jobs,q.summary.visits,q.summary.attachments].map(esc)])}<div class="actions">${button("receive-workspace","Replace current working copy",{},"primary")}${button("discard-incoming","Keep current copy")}</div></div>`}
function render(){const pages={overview,sites:sitesPage,intake:intakePage,quotes:quotesPage,jobs:jobsPage,visits:visitsPage,files:filesPage,workspace:workspacePage};root.innerHTML=`<header><h1>Stove work and handover</h1><p>Retain the enquiry, measured survey, accepted scope, field evidence and each completed handover. Continue later service from the same property and appliance.</p><div class="toolbar"><label>Operator <select id="operator" data-selection="operator">${CAT.operators.map(x=>`<option value="${esc(x.key)}" ${x.key===op?"selected":""}>${esc(x.name)}</option>`).join("")}</select></label><span class="small">Working revision ${w.revision}</span>${button("export-working","Save working JSON")}${button("nav","Workspace & reopen",{tab:"workspace"},"quiet")}</div></header><nav aria-label="Operating sections">${[["overview","Overview & day"],["sites","Sites & appliances"],["intake","Enquiries & surveys"],["quotes","Quotations"],["jobs","Jobs & handovers"],["visits","Visits & fieldwork"],["files","Files & CSV intake"],["workspace","Workspace & history"]].map(([key,title])=>button("nav",title,{tab:key}).replace("<button",`<button ${key===tab?'aria-current="page"':""}`)).join("")}</nav><div id="status" role="status" aria-live="polite">Saved workspace revision ${w.revision}. Changes take effect when their form is saved.</div><main>${pages[tab]()}</main><footer>Original public workflows checked ${esc(CAT.checkedAt||"13 October 2026")}. Measurements, safety decisions, certificates, customer acceptance and due dates are recorded by the operator. This worksheet sends no message, executes no payment and does not submit a native StovePilot import.</footer>`;}
function fd(formId){const f=$(formId);if(!f)throw Error("This form is no longer open.");return new FormData(f)}
function val(d,k){return str(d.get(k)).trim()}
function values(d,k){return d.getAll(k).map(str).filter(Boolean)}
function fields(d,names){return Object.fromEntries(names.map(n=>[n,val(d,n)]))}
function csvIds(s){return [...new Set(str(s).split(",").map(x=>x.trim()).filter(Boolean))]}
function precise(s,places,label){s=str(s).trim();if(!s)return null;if(!new RegExp("^\\d+(?:\\.\\d{1,"+places+"})?$").test(s))throw Error(label+" must be a nonnegative decimal with at most "+places+" places.");const p=s.split("."),n=Number(p[0])*10**places+Number((p[1]||"").padEnd(places,"0"));if(!Number.isSafeInteger(n))throw Error(label+" is too large.");return n}
function parseRows(text,count,label){return str(text).split(/\r?\n/).filter(x=>x.trim()).map((x,i)=>{const cells=x.split("|").map(s=>s.trim());if(cells.length!==count||!cells[0])throw Error(label+" row "+(i+1)+" needs "+count+" pipe-separated cells.");return cells})}
function retainId(old,label,used,prefix){const found=arr(old).find(x=>x.label===label&&!used.has(x.id));const id=found?.id||C.uid(prefix);used.add(id);return id}
function measurementRows(text,old=[]){const used=new Set();return parseRows(text,4,"Measurement").map(([label,value,unit,source])=>({id:retainId(old,label,used,"measure"),label,value,unit,source}))}
function surveyChecks(text,old=[]){const used=new Set();return parseRows(text,4,"Survey check").map(([label,result,notes,evidence])=>({id:retainId(old,label,used,"survey-check"),label,result,notes,evidenceIds:csvIds(evidence)}))}
function yn(x){if(x==="yes")return true;if(x==="no")return false;throw Error("Enter yes or no for each configured requirement.")}
function checkRows(text,old=[]){const used=new Set();return parseRows(text,3,"Work check").map(([label,required,evidenceRequired])=>({id:retainId(old,label,used,"check"),label,required:yn(required),evidenceRequired:yn(evidenceRequired)}))}
function requirementRows(text,old=[]){const used=new Set();return parseRows(text,3,"Handover requirement").map(([label,kind,required])=>({id:retainId(old,label,used,"requirement"),label,kind,required:yn(required)}))}
function quoteLines(text,old=[]){const used=new Set();return parseRows(text,3,"Quote line").map(([label,quantity,price])=>({id:retainId(old,label,used,"line"),label,quantityMilli:precise(quantity,3,"Quantity"),unitPriceCents:precise(price,2,"Unit price")}))}
function downloading(name,content,mime="application/json"){const b=new Blob([content],{type:mime}),url=URL.createObjectURL(b);urls.add(url);const a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url)},30000)}
function exportWarning(){return !dirty.size||window.confirm("Export the saved workspace? Unsaved form changes are not included and will remain on screen.");}
function b64(bytes){let s="";for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(s)}
function readExactUTF8(bytes){const text=new TextDecoder("utf-8",{fatal:true,ignoreBOM:true}).decode(bytes),back=new TextEncoder().encode(text);if(back.length!==bytes.length||back.some((x,i)=>x!==bytes[i]))throw Error("The original UTF-8 bytes could not be preserved.");return text}
function hashText(text){const x=C.hash(text);return typeof x==="string"?x:x.sha256||String(x)}


function saveRecord(collection,type,record,formId){try{const next=C.mutate(w,{type:type+".save",record,expectedRevision:w.revision});if(!guard(formId))return;selected[collection]=record.id;dirty.clear();changed(next,"Saved "+type+" with complete history.");}catch(e){status(e.message||String(e),true)}}
async function submit(formId){
try{
const d=fd(formId);let r,c,record,id;
switch(formId){
case"site":r=chosen("sites");id=r?.id||C.uid("site");saveRecord("sites","site",{id,operatorKey:op,...fields(d,["customerRef","propertyRef","address","contact","access","notes"])},formId);break;
case"appliance":r=chosen("appliances");saveRecord("appliances","appliance",{id:r?.id||C.uid("appliance"),...fields(d,["label","makeModel","serialNumber","fuelType","location","installedOn","notes"]),siteId:r?.siteId||val(d,"siteId")},formId);break;
case"enquiry":r=chosen("enquiries");saveRecord("enquiries","enquiry",{id:r?.id||C.uid("enquiry"),...fields(d,["applianceId","kind","title","reference","requestedDate","details"]),siteId:r?.siteId||val(d,"siteId"),attachmentIds:values(d,"attachmentIds")},formId);break;
case"enquiry-status":r=chosen("enquiries");mutate({type:r.status==="closed"?"enquiry.reopen":"enquiry.close",id:r.id,reason:val(d,"reason")},formId);break;
case"survey":r=chosen("surveys");saveRecord("surveys","survey",{id:r?.id||C.uid("survey"),siteId:r?.siteId||val(d,"siteId"),...fields(d,["enquiryId","applianceId","replacesSurveyId","conductedAt","author","observations","applianceProposal"]),measurements:measurementRows(val(d,"measurements"),r?.measurements),checks:surveyChecks(val(d,"checks"),r?.checks),attachmentIds:values(d,"attachmentIds")},formId);break;
case"quote":r=chosen("quotes");saveRecord("quotes","quote",{id:r?.id||C.uid("quote"),siteId:r?.siteId||val(d,"siteId"),...fields(d,["enquiryId","surveyId","applianceId","replacesQuoteId","title","issuedOn","validUntil","currency","scope","exclusions","terms"]),lines:quoteLines(val(d,"lines"),r?.lines),discountCents:precise(val(d,"discount"),2,"Discount"),taxBasisPoints:precise(val(d,"tax"),2,"Tax percent"),depositCents:precise(val(d,"deposit"),2,"Deposit"),attachmentIds:values(d,"attachmentIds")},formId);break;
case"quote-decision":mutate({type:"quote.decide",id:selected.quotes,...fields(d,["decision","decidedAt","by","reference","notes"])},formId);break;
case"job":r=chosen("jobs");saveRecord("jobs","job",{id:r?.id||C.uid("job"),siteId:r?.siteId||val(d,"siteId"),...fields(d,["applianceId","enquiryId","quoteId","parentJobId","kind","title","scope","notes"]),checklist:checkRows(val(d,"checklist"),r?.checklist),requirements:requirementRows(val(d,"requirements"),r?.requirements)},formId);break;
case"job-cancel":mutate({type:"job.cancel",id:selected.jobs,reason:val(d,"reason")},formId);break;
case"requirement":mutate({type:"job.requirement",jobId:selected.jobs,...fields(d,["requirementId","status","reference","notes","recordedAt","author"]),attachmentIds:values(d,"attachmentIds")},formId);break;
case"finding":r=chosen("findings");if(r?.jobId!==selected.jobs)r=null;saveRecord("findings","finding",{id:r?.id||C.uid("finding"),jobId:selected.jobs,...fields(d,["visitId","severity","description"]),evidenceIds:values(d,"evidenceIds")},formId);break;
case"finding-status":r=chosen("findings");mutate({type:r.status==="resolved"?"finding.reopen":"finding.resolve",id:r.id,...(r.status==="resolved"?{reason:val(d,"reason")}:{resolution:val(d,"reason"),evidenceIds:values(d,"evidenceIds")})},formId);break;
case"payment":mutate({type:"payment.add",record:{id:C.uid("payment"),jobId:selected.jobs,...fields(d,["kind","currency","paidAt","reference","notes","correctsPaymentId"]),amountCents:precise(val(d,"amount"),2,"Payment amount")}},formId);break;
case"service-plan":r=chosen("servicePlans");if(r?.jobId!==selected.jobs)r=null;saveRecord("servicePlans","servicePlan",{id:r?.id||C.uid("service"),jobId:selected.jobs,...fields(d,["applianceId","dueOn","reason","notes"])},formId);break;
case"service-link":mutate({type:"servicePlan.link",id:selected.servicePlans,targetJobId:val(d,"targetJobId")},formId);break;
case"service-status":r=chosen("servicePlans");mutate({type:r.status==="closed"?"servicePlan.reopen":"servicePlan.close",id:r.id,reason:val(d,"reason")},formId);break;
case"visit":r=chosen("visits");saveRecord("visits","visit",{id:r?.id||C.uid("visit"),jobId:r?.jobId||val(d,"jobId"),...fields(d,["kind","startAt","endAt","timezone","notes"]),workerRefs:val(d,"workerRefs").split(/\r?\n/).map(x=>x.trim()).filter(Boolean)},formId);break;
case"visit-confirm":if(!reviews.visit)throw Error("Review the saved visit again.");mutate({type:"visit.confirm",id:selected.visits,expectedReviewSha:reviews.visit.reviewSha256,...fields(d,["confirmedBy","reference"])},formId);break;
case"visit-start":mutate({type:"visit.start",id:selected.visits,...fields(d,["startedAt","author"])},formId);break;
case"visit-finish":mutate({type:"visit.finish",id:selected.visits,...fields(d,["finishedAt","author","notes"])},formId);break;
case"visit-abort":mutate({type:"visit.abort",id:selected.visits,...fields(d,["finishedAt","author","reason"])},formId);break;
case"visit-cancel":mutate({type:"visit.cancel",id:selected.visits,reason:val(d,"reason")},formId);break;
case"field":{const view=C.visitView(w,selected.visits);const checkResults=arr(view.job.checklist).filter(x=>val(d,"check-result-"+x.id)).map(x=>({checkId:x.id,result:val(d,"check-result-"+x.id),notes:val(d,"check-notes-"+x.id),evidenceIds:csvIds(val(d,"check-evidence-"+x.id))}));mutate({type:"field.add",record:{id:C.uid("field"),visitId:selected.visits,...fields(d,["recordedAt","author","notes"]),measurements:measurementRows(val(d,"measurements")),checkResults,attachmentIds:values(d,"attachmentIds")}},formId);break;}
case"handover":{const ack=fields(d,["ackAt","ackBy","ackReference"]),input={jobId:selected.jobs,...fields(d,["completedAt","author","summary","notes"]),documentIds:values(d,"documentIds"),customerAcknowledgement:ack.ackAt||ack.ackBy||ack.ackReference?{at:ack.ackAt,by:ack.ackBy,reference:ack.ackReference}:null};const review=C.reviewHandover(w,input);reviews.handover={input,review};$("handover-review").innerHTML=issueList(review)+details("Exact reviewed handover snapshot",json(review.snapshot))+button("handover-commit","Commit this reviewed handover",{},"primary",!review.canCommit);status("Reviewed the saved job with this handover input. No completion has been committed.");break;}
case"attachment":await addFile(d);break;
case"import-select":{const input={attachmentId:val(d,"attachmentId"),operatorKey:op,entity:val(d,"entity"),mapping:{},constants:{}};const review=C.reviewImport(w,input);if(!guard(formId))break;importInput=input;importReview=review;dirty.clear();epoch++;render();status("Original headers loaded. Choose every mapping and row decision explicitly.");break;}
case"import-map":{if(!importInput||!importReview)throw Error("Choose the original CSV first.");const mapping={},constants={};for(const key of importFields[importInput.entity]){const h=val(d,"map-"+key),v=val(d,"constant-"+key);if(h&&v)throw Error(key+": choose a source header or an explicit constant.");if(h)mapping[key]=h;if(v)constants[key]=v;}if(val(d,"constant-siteId"))constants.siteId=val(d,"constant-siteId");const input={...importInput,mapping,constants},review=C.reviewImport(w,input);if(!guard(formId))break;importInput=input;importReview=review;dirty.clear();epoch++;render();status("Mapped source reviewed. Choose create, link or ignore for every row.");break;}
case"import-decisions":{if(!importInput||!importReview)throw Error("Review the original mapped CSV first.");const decisions=importReview.rows.map(row=>{const action=val(d,"action-"+row.rowId);if(!action)throw Error("Select a decision for original row "+row.line);return {rowId:row.rowId,action,...(action==="create"?{id:val(d,"new-"+row.rowId)}:{}),...(action==="link"?{targetId:val(d,"target-"+row.rowId)}:{}),reason:val(d,"reason-"+row.rowId)}});mutate({type:"import.commit",input:importInput,decisions,expectedReviewSha:importReview.reviewSha256},formId,"Imported explicit row decisions with original source and full history.");break;}
default:throw Error("Unknown form.");
}
}catch(e){status(e.message||String(e),true)}
}
async function addFile(d){const file=d.get("original");if(!file||!file.name)throw Error("Choose an original file.");const token=++readEpoch.file,atEpoch=epoch,atRevision=w.revision,atId=w.id,operator=op;const current=()=>token===readEpoch.file&&epoch===atEpoch&&w.revision===atRevision&&w.id===atId&&op===operator&&tab==="files";const context=fields(d,["siteId","jobId","description"]);try{if(file.size>8*1024*1024)throw Error("The original exceeds the 8 MiB per-file limit.");status("Reading exact original bytes…");const bytes=new Uint8Array(await file.arrayBuffer());if(!current())return;if(bytes.length!==file.size)throw Error("The selected file changed while being read.");mutate({type:"attachment.add",record:{id:C.uid("file"),name:file.name,mime:file.type||"application/octet-stream",base64:b64(bytes),...context}},"attachment","Original file retained byte-for-byte.");}catch(e){if(current())throw e;}}
async function readWorkspace(file){epoch++;const token=++readEpoch.workspace;pendingWorkspace=null;const host=$("incoming-review");if(host)host.innerHTML="";if(!file)return;const atEpoch=epoch,atRevision=w.revision,atId=w.id;const current=()=>token===readEpoch.workspace&&epoch===atEpoch&&w.revision===atRevision&&w.id===atId&&tab==="workspace";try{if(file.size>64*1024*1024)throw Error("The selected workspace exceeds 64 MiB.");status("Reading and validating the complete working copy…");const bytes=new Uint8Array(await file.arrayBuffer());if(!current())return;if(bytes.length!==file.size)throw Error("The selected file changed while being read.");const text=readExactUTF8(bytes),candidate=C.importWorkspace(text,CAT);if(!current())return;pendingWorkspace={workspace:candidate,bytes:bytes.length,sha:hashText(text),summary:C.summary(candidate),baseId:w.id,baseRevision:w.revision};const el=$("incoming-review");if(el)el.innerHTML=incomingView();status("Incoming working copy is validated. Current work has not been replaced.");}catch(e){if(current()){pendingWorkspace=null;const el=$("incoming-review");if(el)el.innerHTML="";status(e.message||String(e),true);}}finally{if(token===readEpoch.workspace&&$("workspace-file"))$("workspace-file").value="";}}
async function example(){if(busy||!guard())return;if(!window.confirm("Replace the current working copy with the complete fictional worked programme? Download your current JSON first if you need to retain it."))return;dirty.clear();clearTransient();const savedEpoch=epoch,savedId=w.id,savedRevision=w.revision;busy=true;root.setAttribute("aria-busy","true");const current=()=>savedEpoch===epoch&&savedId===w.id&&savedRevision===w.revision;try{status("Building the complete worked programme…");const out=await E.buildAsync(C,CAT,p=>{if(current()&&$("example-progress"))$("example-progress").textContent=`${p.completed} / ${p.total} — ${p.label}`;});if(!current()){if(tab==="workspace")status("The worked programme was not applied because you changed the current view or work.");return;}w=out.workspace;selected={};importInput=null;dirty.clear();clearTransient();busy=false;render();status("Complete fictional worked programme loaded. Actual customer work is entered separately.");}catch(e){if(current())status(e.message||String(e),true);}finally{busy=false;root.removeAttribute("aria-busy");}}
function action(el){const a=el.dataset.action,id=el.dataset.id,c=el.dataset.collection;try{
if(a==="nav"){navigate(el.dataset.tab);return;}
if(a==="open"){open(c,id);return;}
if(a==="new"){navigate(c==="sites"||c==="appliances"?"sites":c==="enquiries"||c==="surveys"?"intake":c==="quotes"?"quotes":c==="visits"?"visits":"jobs",{[c]:null});return;}
if(a==="choose-finding"||a==="choose-plan"){navigate("jobs",{[a==="choose-finding"?"findings":"servicePlans"]:id||null});return;}
if(a==="review-survey"){reviews.survey=C.reviewSurvey(w,id);$("survey-review").innerHTML=issueList(reviews.survey)+button("finalize-survey","Finalize this saved survey",{id},"primary",!reviews.survey.canFinalize);return;}
if(a==="finalize-survey"){if(!reviews.survey)throw Error("Review the saved survey first.");mutate({type:"survey.finalize",id,expectedReviewSha:reviews.survey.reviewSha256});return;}
if(a==="review-quote"){reviews.quote=C.reviewQuote(w,id);$("quote-review").innerHTML=issueList(reviews.quote)+totalsView(find("quotes",id),reviews.quote.totals)+button("issue-quote","Issue this saved quotation",{id},"primary",!reviews.quote.canIssue);return;}
if(a==="issue-quote"){if(!reviews.quote)throw Error("Review the saved quotation first.");mutate({type:"quote.issue",id,expectedReviewSha:reviews.quote.reviewSha256});return;}
if(a==="review-visit"){reviews.visit=C.reviewVisit(w,id);$("visit-review").innerHTML=issueList(reviews.visit)+table(["Conflicting visit","Workers","Reason"],arr(reviews.visit.conflicts).map(x=>[esc(x.visitId),esc(arr(x.workerRefs).join(", ")),esc(x.reason)]))+(reviews.visit.canConfirm?form("visit-confirm",input("confirmedBy","Confirmed by","","text",{required:true})+input("reference","Actual confirmation reference","","text",{required:true}),"Confirm this reviewed visit"):"");return;}
if(a==="handover-commit"){if(!reviews.handover)throw Error("Review these exact handover details again.");mutate({type:"handover.commit",input:reviews.handover.input,expectedReviewSha:reviews.handover.review.reviewSha256},"handover","Completed handover saved as an exact preserved edition.");return;}
if(a==="survey-replace"){const r=find("surveys",id),record={id:C.uid("survey"),...Object.fromEntries(["siteId","enquiryId","applianceId","observations","applianceProposal","measurements","checks","attachmentIds"].map(k=>[k,r[k]])),replacesSurveyId:id,conductedAt:"",author:""};saveRecord("surveys","survey",record,null);return;}
if(a==="quote-replace"){const r=find("quotes",id),record={id:C.uid("quote"),...Object.fromEntries(["siteId","enquiryId","surveyId","applianceId","title","currency","scope","exclusions","terms","lines","discountCents","taxBasisPoints","depositCents","attachmentIds"].map(k=>[k,r[k]])),replacesQuoteId:id,issuedOn:"",validUntil:""};saveRecord("quotes","quote",record,null);return;}
if(a==="attachment-download"){const r=find("attachments",id);downloading(r.name,C.attachmentBytes(w,id),r.mime);return;}
if(a==="handover-download"){downloading("handover-"+id+".html",C.handoverHTML(w,id),"text/html;charset=utf-8");return;}
if(a==="export-working"){if(exportWarning())downloading("stove-working-"+w.id+".json",C.exportWorkspace(w));return;}
if(a==="export-report"||a==="export-all-report"){if(exportWarning())downloading("stove-work-report.html",C.reportHTML(w,a==="export-report"?op:undefined),"text/html;charset=utf-8");return;}
if(a==="export-csv"||a==="export-all-csv"){if(exportWarning())downloading("stove-work-records.csv",C.exportCSV(w,a==="export-csv"?op:undefined),"text/csv;charset=utf-8");return;}
if(a==="save-browser"){if(!exportWarning())return;localStorage.setItem("stove-operations-working-copy",C.exportWorkspace(w));status("Separate browser copy saved. Keep a downloaded JSON for independent custody.");return;}
if(a==="load-browser"){if(!guard())return;const text=localStorage.getItem("stove-operations-working-copy");if(!text)throw Error("No separate browser copy is saved here.");const candidate=C.importWorkspace(text,CAT);dirty.clear();clearTransient();tab="workspace";pendingWorkspace={workspace:candidate,bytes:C.bytes(text).length??C.bytes(text),sha:hashText(text),summary:C.summary(candidate),baseId:w.id,baseRevision:w.revision};render();status("Saved browser copy reviewed without replacing current work.");return;}
if(a==="receive-workspace"){if(!pendingWorkspace)throw Error("Choose and validate a full working JSON first.");if(pendingWorkspace.baseId!==w.id||pendingWorkspace.baseRevision!==w.revision)throw Error("Current work changed. Review the incoming copy again.");if(!guard()||!window.confirm("Replace the current working copy with this validated separate copy?"))return;const next=pendingWorkspace.workspace;selected={};importInput=null;dirty.clear();changed(next,"Complete working copy received; original bytes and history are retained.");return;}
if(a==="discard-incoming"){pendingWorkspace=null;readEpoch.workspace++;const host=$("incoming-review");if(host)host.innerHTML="";status("Current working copy retained.");return;}
if(a==="new-workspace"){if(!guard()||!window.confirm("Create an empty workspace? Download the current complete JSON first if needed."))return;selected={};importInput=null;dirty.clear();changed(C.create(CAT,{id:C.uid("stove"),title:"Stove work and handover"}),"Empty workspace created. No actual customer or technical data was inferred.");return;}
if(a==="example"){example();return;}
}catch(e){status(e.message||String(e),true)}
}
root.addEventListener("submit",e=>{const formEl=e.target.closest("form[data-form]");if(!formEl)return;e.preventDefault();submit(formEl.dataset.form);});
root.addEventListener("click",e=>{const el=e.target.closest("[data-action]");if(el&&!el.disabled)action(el)});
root.addEventListener("input",e=>{const f=e.target.closest("form[data-form]");if(f){dirty.add(f.dataset.form);epoch++;if(f.dataset.form==="handover"){delete reviews.handover;const commit=root.querySelector('[data-action="handover-commit"]');if(commit)commit.disabled=true;}}});
root.addEventListener("change",e=>{const el=e.target;if(el.id==="workspace-file"){readWorkspace(el.files?.[0]);return;}if(el.dataset.selection==="operator"){const value=el.value;if(!guard()){el.value=op;return;}op=value;selected={};importInput=null;dirty.clear();clearTransient();render();return;}if(el.dataset.selection==="day"){const value=el.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)){el.value=date;status("Choose a complete calendar date.",true);return;}if(!guard()){el.value=date;return;}date=value;dirty.clear();clearTransient();render();return;}const f=el.closest("form[data-form]");if(f){dirty.add(f.dataset.form);epoch++;if(f.dataset.form==="handover"){delete reviews.handover;const commit=root.querySelector('[data-action="handover-commit"]');if(commit)commit.disabled=true;}}});
window.addEventListener("beforeunload",e=>{if(dirty.size){e.preventDefault();e.returnValue=""}});
window.addEventListener("pagehide",()=>{clearTransient();for(const url of urls)URL.revokeObjectURL(url);urls.clear();});
render();

